		expect(normalizeMode()).toBe('')
		expect(normalizeMode(null)).toBe('')
	})
})

describe('parseExtensionEntry', () => {
	it('괄호가 없으면 확장자 하나로 처리한다', () => {
		expect(parseExtensionEntry('PDF')).toEqual(['.pdf'])
	})

	it('괄호 안의 확장자를 모두 분리하며 점을 중복해서 붙이지 않는다', () => {
		expect(parseExtensionEntry('엑셀(xlsx,xls)')).toEqual(['.xlsx', '.xls'])
	})

	it('구분자 주변 공백과 이미 붙은 점을 정리한다', () => {
		expect(parseExtensionEntry('이미지( .jpg , JPEG , png )')).toEqual(['.jpg', '.jpeg', '.png'])
	})

	it('값이 비어 있으면 빈 배열을 반환한다', () => {
		expect(parseExtensionEntry('')).toEqual([])
		expect(parseExtensionEntry(null)).toEqual([])
		expect(parseExtensionEntry('   ')).toEqual([])
	})

	it('ocr 모드에서는 처리 불가 확장자를 제외한다', () => {
		expect(parseExtensionEntry('txt', 'ocr')).toEqual([])
		expect(parseExtensionEntry('문서(pdf,txt,md)', 'ocr')).toEqual(['.pdf'])
	})

	it('호출부가 대문자 OCR 을 넘겨도 동일하게 제외한다', () => {
		expect(parseExtensionEntry('문서(pdf,txt,md)', 'OCR')).toEqual(['.pdf'])
	})

	it('ocr 이 아닌 모드에서는 제외하지 않는다', () => {
		expect(parseExtensionEntry('문서(pdf,txt)', 'simple')).toEqual(['.pdf', '.txt'])
	})
})

describe('buildAcceptString', () => {
	it('useYn 이 Y 인 항목만 사용한다', () => {
		const accept = buildAcceptString([
			{ name: 'PDF', useYn: 'Y' },
			{ name: 'HWP', useYn: 'N' },
			{ name: '엑셀(xlsx,xls)', useYn: 'Y' },
		])

		expect(accept).toBe('.pdf,.xlsx,.xls')
	})

	it('중복 확장자를 제거한다', () => {
		const accept = buildAcceptString([
			{ name: '이미지(jpg,png)', useYn: 'Y' },
			{ name: 'PNG', useYn: 'Y' },
		])

		expect(accept).toBe('.jpg,.png')
	})

	it('배열이 아니면 빈 문자열을 반환한다', () => {
		expect(buildAcceptString(undefined)).toBe('')
		expect(buildAcceptString(null)).toBe('')
		expect(buildAcceptString({})).toBe('')
	})

	it('ocr 모드에서 제외된 확장자만 남은 항목은 결과에서 빠진다', () => {
		const accept = buildAcceptString([
			{ name: '텍스트(txt,md)', useYn: 'Y' },
			{ name: 'PDF', useYn: 'Y' },
		], 'OCR')

		expect(accept).toBe('.pdf')
	})
})

describe('buildFallbackAccept', () => {
	it('기본 확장자 목록을 accept 문자열로 만든다', () => {
		expect(buildFallbackAccept()).toContain('.pdf')
		expect(buildFallbackAccept()).toContain('.txt')
	})

	it('OCR 모드에서는 처리 불가 확장자를 포함하지 않는다', () => {
		const accept = buildFallbackAccept('OCR').split(',')

		OCR_EXCLUDE_EXT.forEach((ext) => {
			expect(accept).not.toContain(`.${ext}`)
		})
		expect(accept).toContain('.pdf')
	})
})

describe('resolveMaxSizeMb', () => {
	it('simple 모드는 simpleBotFileLimit 을 사용한다', () => {
		expect(resolveMaxSizeMb({ simpleBotFileLimit: 20, ocrFileLimit: 10 }, 'simple')).toBe(20)
	})

	it('대문자 OCR 로 호출해도 ocrFileLimit 을 사용한다', () => {
		expect(resolveMaxSizeMb({ simpleBotFileLimit: 20, ocrFileLimit: 10 }, 'OCR')).toBe(10)
	})

	it('모드나 정책 값이 없으면 기본값을 사용한다', () => {
