import { ref, computed, watch } from 'vue';
import IconBtn from '../common/button/IconBtn.vue';
import SmLoading from '../common/loader/SmLoading.vue';
import { inf } from '@/api/interface';
import { isSuccess, toast } from '@/utils/common';
import { readUser } from '@/storage/userStorage';
import { createSharedApp } from '@/utils/shareAppService';
import TextIconBtn from '../common/button/TextIconBtn.vue';
import { useRouter } from 'vue-router';
const props = defineProps({
    open: {
        type: Boolean,
        default: false
    }
});
const router = useRouter()
const projectList = ref([]);
const isLoading = ref(false)
const emit = defineEmits(['close']);
const close = () => {
    emit('close');
};

const selectedProject = ref(null);
const appId = ref('');

const getList = async() =>{
    try {
        isLoading.value = true
        const res = await inf.athena.shareList.call()
        if(!isSuccess()){
            projectList.value = []
        }
        projectList.value = res.data.body ?? []
    } catch (e) {
        projectList.value = []
        close()
    }finally{
        isLoading.value = false
    }
}

const selectProject = (project) => {
    if (selectedProject.value?.id === project.id) {
        selectedProject.value = null;
        appId.value = '';
        return;
    }

    selectedProject.value = project;
    appId.value = '';
};

const isShareDisabled = computed(() => {
    return !selectedProject.value || !appId.value.trim();
});

const submitShare = () => {
    if (isShareDisabled.value) return;

    emit('share', {
        projectId: selectedProject.value.id,
        projectName: selectedProject.value.name,
        appId: appId.value.trim(),
    });
};
const gotoShare = () => {
    close()
	router.push({ path: '/share/list' })
}
const onShareAppSubmit = async () => {
    const shareInfo = selectedProject.value ?? {}
	const userId = String(readUser()?.user_id || '').trim()
	const projectId = String(shareInfo.id).trim()
	const aId = String(appId.value || '').trim()

	if (!userId) {
		toast('사용자 정보가 없습니다. 다시 로그인해주세요.')
		return
	}
	if (!projectId) {
		toast('프로젝트 정보가 없습니다. 다시 진입 후 시도해주세요.')
		return
	}
	if (!aId) {
		toast('App ID를 입력해주세요.')
		return
	}

	try {
		const result = await createSharedApp({
			project_id: projectId,
			user_id: userId,
			app_id: aId,
		})

		if(!result.ok){
			toast('권한이 없어 설치가 불가합니다. 관리자에게 문의해 주시기 바랍니다.')
			return
		}

		toast('공유 앱이 등록되었습니다.')
		if (result?.url) {
			window.open(result.url, '_blank')
		}
        close()

	} catch (e) {
		if(e == 'COM') return
		toast('요청 처리 중 오류가 발생했습니다.')
	} finally {
		isLoading.value = false
	}
}

watch(() => props.open, (v) => {
	if (!v) return
	getList()
}, {immediate:true})

</script>

